package za.co.erraco.disputes;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.math.BigDecimal; import java.util.*; import org.junit.jupiter.api.Test;
class DisputeServiceTest { @Test void opensDisputeForPostedTransaction(){ var tr=mock(TransactionRepository.class);var dr=mock(DisputeRepository.class);var t=new Transaction();t.id=7L;t.status="POSTED"; when(tr.findById(7L)).thenReturn(Optional.of(t)); when(dr.save(any())).thenAnswer(i->i.getArgument(0)); var result=new DisputeService(tr,dr).dispute(7L,"  Not recognised  "); assertEquals("DISPUTED",t.status);assertEquals("Not recognised",result.reason);verify(dr).save(any()); } @Test void rejectsNonPostedTransaction(){var tr=mock(TransactionRepository.class);var dr=mock(DisputeRepository.class);var t=new Transaction();t.status="DISPUTED";when(tr.findById(1L)).thenReturn(Optional.of(t));assertThrows(DisputeService.TransactionNotEligibleException.class,()->new DisputeService(tr,dr).dispute(1L,"Duplicate"));} @Test void rejectsUnknownTransaction(){var tr=mock(TransactionRepository.class);var dr=mock(DisputeRepository.class);when(tr.findById(99L)).thenReturn(Optional.empty());assertThrows(DisputeService.TransactionNotFoundException.class,()->new DisputeService(tr,dr).dispute(99L,"Unknown"));}}
